document.documentElement.setAttribute("data-theme", theme);
try {
  localStorage.setItem("soar.theme", theme);
} catch {
  // Private window, blocked site data. The theme still applies for this view.
}

const { byName } = globalThis.SOAR;

const holder = byName("newClientEmails");
if (!holder) return null;

const row = document.createElement("div");
row.className = "email-row";

const input = document.createElement("input");
input.type = "email";
input.placeholder = "soc@client.example";
input.className = "client-email";
row.append(input);

// The first address has no remove button: a client with no way to be
// contacted is not a client anyone can run a service for.
if (holder.children.length) {
  const drop = document.createElement("button");
  drop.type = "button";
  drop.className = "ghost";
  drop.textContent = "Remove";
  drop.addEventListener("click", () => row.remove());
  row.append(drop);
}

holder.append(row);
input.focus();
return row;

const { byName, request } = globalThis.SOAR;

return (async () => {
addEmailField(null);

const catalogue = await request("GET", "/api/connectors");
const holder = byName("newClientTools");
if (!holder) return null;
holder.replaceChildren();

// Grouped, and SIEM first: without one nothing arrives, and an EDR is
// the only thing that can act on a host once it does.
const order = ["siem", "edr", "identity", "email", "network", "ticketing",
               "chat", "paging", "threat_intel"];
const groups = new Map();
for (const tool of catalogue.items || []) {
  if (!groups.has(tool.category)) groups.set(tool.category, []);
  groups.get(tool.category).push(tool);
}

const seen = [...groups.keys()].sort((a, b) => {
  const ai = order.indexOf(a), bi = order.indexOf(b);
  return (ai < 0 ? 99 : ai) - (bi < 0 ? 99 : bi);
});

for (const category of seen) {
  const head = document.createElement("div");
  head.className = "cat-head";
  head.textContent = category.replace("_", " ").toUpperCase();
  holder.append(head);

  const grid = document.createElement("div");
  grid.className = "tool-grid";
  for (const tool of groups.get(category)) {
    const pick = document.createElement("label");
    pick.className = "tool-pick";
    const box = document.createElement("input");
    box.type = "checkbox";
    box.value = tool.id;
    box.className = "tool-choice";
    pick.append(box);
    const text = document.createElement("span");
    text.textContent = `${tool.name}  (${tool.commands})`;
    pick.append(text);
    grid.append(pick);
  }
  holder.append(grid);
}
return seen.length;
})();

const { byName, request } = globalThis.SOAR;

return (async () => {
const error = byName("newClientError");
if (error) error.textContent = "";

const name = (byName("newClientName")?.value || "").trim();
if (!name) {
  if (error) error.textContent = "A client needs a name.";
  return null;
}

const emails = [...document.querySelectorAll(".client-email")]
  .map((i) => i.value.trim()).filter(Boolean);
const connectors = [...document.querySelectorAll(".tool-choice:checked")]
  .map((i) => i.value);

try {
  const created = await request("POST", "/api/clients",
                                { name, contact_emails: emails, connectors });
  window.location.href = `/client.html?id=${encodeURIComponent(created.id)}`;
  return created;
} catch (failure) {
  if (error) error.textContent = failure.message;
  return null;
}
})();

const { byName, request, setText } = globalThis.SOAR;

return (async () => {
const data = await request("GET", "/api/integrations");
setText("liveCount", `${data.live} connected`);
setText("pendingCount", `${data.pending} waiting`);

const holder = byName("integrationsList");
holder.replaceChildren();

if (!(data.clients || []).length) {
  const none = document.createElement("div");
  none.className = "conn-empty";
  none.textContent = "No clients yet. Add one under Clients.";
  holder.append(none);
  return data;
}

for (const client of data.clients) {
  const block = document.createElement("div");
  block.className = "client-block";

  const bar = document.createElement("div");
  bar.className = "client-bar";
  const who = document.createElement("span");
  who.className = "who";
  who.textContent = client.client_name;
  const tally = document.createElement("span");
  tally.className = "tally";
  tally.textContent = `${client.live.length} connected · `
                    + `${client.pending.length} waiting`;
  bar.append(who, tally);
  block.append(bar);

  if (!client.live.length && !client.pending.length) {
    const none = document.createElement("div");
    none.className = "conn-empty";
    none.textContent = "No tools recorded. Nothing can reach this client.";
    block.append(none);
  }

  for (const row of client.live) {
    block.append(liveConnectorCard(client, row));
  }
  for (const row of client.pending) {
    block.append(pendingConnectorCard(row));
  }
  holder.append(block);
}
return data;
})();

const { request } = globalThis.SOAR;

const card = document.createElement("div");
card.className = "conn";

const line = document.createElement("div");
line.className = "conn-line";

const cat = document.createElement("span");
cat.className = "conn-cat";
cat.textContent = row.category || "";
const nm = document.createElement("span");
nm.className = "conn-name";
nm.textContent = row.name;
const grow = document.createElement("span");
grow.className = "conn-grow";
grow.textContent = row.last_error || "";

const intake = document.createElement("span");
intake.className = row.intake_configured ? "chip" : "chip chip-attn";
intake.textContent = row.intake_configured
  ? "intake configured" : "intake not set up";

const health = document.createElement("span");
const grade = { healthy: "low", degraded: "medium", failing: "critical" };
health.className = `sev sev-${grade[row.health] || "low"}`;
health.textContent = row.health;

const configure = document.createElement("button");
configure.type = "button";
configure.className = "ghost";
configure.textContent = "Alert intake";

line.append(cat, nm, grow, intake, health, configure);
card.append(line);

const drawer = document.createElement("div");
drawer.className = "conn-form";
let drawn = false;
configure.addEventListener("click", async () => {
  drawer.classList.toggle("is-open");
  if (drawn || !drawer.classList.contains("is-open")) return;
  drawn = true;
  const reply = await request(
    "GET", `/api/clients/${encodeURIComponent(client.client_id)}/intake`);
  const source = (reply.items || [])
    .find((i) => i.source === row.connector_id);
  if (source) {
    drawer.append(intakeSourcePanel(client.client_id, source));
  } else {
    const problem = document.createElement("div");
    problem.className = "conn-empty";
    problem.textContent = "This connector is not reporting as live yet.";
    drawer.append(problem);
  }
});
card.append(drawer);
return card;

const { request, setText } = globalThis.SOAR;

const card = document.createElement("div");
card.className = "conn";

const line = document.createElement("div");
line.className = "conn-line";
const cat = document.createElement("span");
cat.className = "conn-cat";
cat.textContent = row.category || "";
const nm = document.createElement("span");
nm.className = "conn-name";
nm.textContent = row.name;
const grow = document.createElement("span");
grow.className = "conn-grow";
grow.textContent = `waiting on ${(row.credential_roles || []).join(", ")
                     || "credentials"}`;

const open = document.createElement("button");
open.type = "button";
open.className = "accent";
open.textContent = "Connect";
line.append(cat, nm, grow, open);
card.append(line);

const form = document.createElement("div");
form.className = "conn-form";

if ((row.min_vendor_permissions || []).length) {
  const perms = document.createElement("div");
  perms.className = "conn-perms";
  perms.textContent = `Needs on the vendor side: ${
    row.min_vendor_permissions.join(", ")}`;
  form.append(perms);
}

// Connection settings first, because they are what makes the endpoint
// exist. No two vendors want the same ones: a Falcon cloud, a Sentinel
// workspace, a Splunk management port - all from the manifest.
const settings = {};
for (const spec of row.setup || []) {
  const field = document.createElement("div");
  field.className = "conn-field";
  const label = document.createElement("label");
  label.textContent = spec.label + (spec.required ? "" : " (optional)");

  let control;
  if (spec.kind === "select") {
    control = document.createElement("select");
    for (const option of spec.options || []) {
      const item = document.createElement("option");
      item.value = option.value;
      item.textContent = option.label;
      control.append(item);
    }
  } else {
    control = document.createElement("input");
    control.type = spec.kind === "url" ? "url" : "text";
    control.placeholder = spec.placeholder || "";
  }
  if (spec.default) control.value = spec.default;
  settings[spec.name] = control;
  field.append(label, control);
  form.append(field);

  if (spec.help) {
    const help = document.createElement("div");
    help.className = "conn-perms";
    help.textContent = spec.help;
    form.append(help);
  }
}

const inputs = {};
for (const role of row.credential_roles || []) {
  const field = document.createElement("div");
  field.className = "conn-field";
  const label = document.createElement("label");
  label.textContent = role;
  const input = document.createElement("input");
  // type=password so a key is not left legible on a shared screen while
  // someone reads the next one out.
  input.type = "password";
  input.autocomplete = "off";
  input.placeholder = role;
  inputs[role] = input;
  field.append(label, input);
  form.append(field);
}

const howField = document.createElement("div");
howField.className = "conn-field";
const howLabel = document.createElement("label");
howLabel.textContent = "alerts arrive by";
const how = document.createElement("select");
for (const [value, text] of [["poll", "polling (we fetch)"],
                             ["webhook", "webhook (they push)"],
                             ["none", "no alerts from this tool"]]) {
  const option = document.createElement("option");
  option.value = value;
  option.textContent = text;
  how.append(option);
}
howField.append(howLabel, how);
form.append(howField);

const hookField = document.createElement("div");
hookField.className = "conn-field";
const hookLabel = document.createElement("label");
hookLabel.textContent = "webhook path";
const hook = document.createElement("input");
hook.type = "text";
hook.placeholder = `/ingest/${row.connector_id}`;
hookField.append(hookLabel, hook);
hookField.hidden = true;
how.addEventListener("change", () => {
  hookField.hidden = how.value !== "webhook";
});
form.append(hookField);

const save = document.createElement("button");
save.type = "button";
save.className = "accent";
save.textContent = "Save and connect";
const problem = document.createElement("span");
problem.className = "login-error";

save.addEventListener("click", async () => {
  const credentials = {};
  for (const [role, input] of Object.entries(inputs)) {
    credentials[role] = input.value;
  }
  try {
    const config = {};
    for (const [name, control] of Object.entries(settings)) {
      if (control.value) config[name] = control.value;
    }
    const done = await request(
      "POST", `/api/integrations/${encodeURIComponent(row.id)}/connect`,
      { credentials, config, ingest_kind: how.value,
        webhook_path: hook.value || null });
    setText("statusMessage",
            `${done.connector} is live, ${done.commands} commands published`);
    await loadIntegrations();
  } catch (failure) {
    problem.textContent = failure.message;
  }
});

const actions = document.createElement("div");
actions.className = "conn-field";
actions.append(save, problem);
form.append(actions);

open.addEventListener("click", () => {
  form.classList.toggle("is-open");
  const first = Object.values(inputs)[0];
  if (form.classList.contains("is-open") && first) first.focus();
});

card.append(form);
return card;

return (async () => {
return await loadIntegrations();
})();

const { byName, request, setText } = globalThis.SOAR;

return (async () => {
const id = new URLSearchParams(location.search).get("id");
if (!id) { setText("statusMessage", "no client selected"); return null; }

const clients = await request("GET", "/api/clients");
const me_client = clients.active;
const client = (clients.items || []).find((c) => c.id === id);
if (!client) { setText("statusMessage", "no such client"); return null; }

if (me_client !== id) {
  await request("POST", "/api/session/client", { client_id: id });
}

setText("clientName", client.name);
setText("clientReference", client.reference || "no reference");
renderClientEndOfLife(client);
byName("clientNameInput").value = client.name || "";
byName("clientRefInput").value = client.reference || "";
byName("clientContactInput").value = client.contact_email || "";
byName("clientTierInput").value = client.tier || "standard";
byName("clientTzInput").value = client.timezone || "UTC";

const tools = await request("GET", `/api/clients/${encodeURIComponent(id)}/tools`);

// The catalogue, grouped so the two that matter most are asked for first:
// without a SIEM nothing arrives, and without an EDR nothing can be
// contained.
const order = ["siem", "edr", "identity", "email", "network", "ticketing",
               "intel"];
const available = (tools.available || []).slice().sort((a, b) =>
  (order.indexOf(a.category) + 99 * (order.indexOf(a.category) < 0))
  - (order.indexOf(b.category) + 99 * (order.indexOf(b.category) < 0))
  || a.name.localeCompare(b.name));

const list = byName("toolList");
list.replaceChildren();
for (const tool of available) {
  const row = document.createElement("div");
  row.className = "tool-row";

  const cat = document.createElement("span");
  cat.className = "tool-cat";
  cat.textContent = tool.category;
  row.append(cat);

  const name = document.createElement("span");
  name.textContent = `${tool.name}  (${tool.commands} commands)`;
  name.style.flex = "1";
  row.append(name);

  if (tool.installed) {
    const done = document.createElement("span");
    done.className = "chip";
    done.textContent = "connected";
    row.append(done);
  } else {
    const connect = document.createElement("button");
    connect.type = "button";
    connect.className = "ghost";
    connect.textContent = "Connect";
    connect.addEventListener("click", () => connectTool(id, tool));
    row.append(connect);
  }
  list.append(row);
}

const installed = byName("installedList");
installed.replaceChildren();
const live = (tools.installed || []).filter((t) => t.status === "live");
const waiting = (tools.installed || []).filter((t) => t.status !== "live");

if (!live.length) {
  const none = document.createElement("div");
  none.className = "hint";
  none.textContent = "Nothing connected yet. Until a SIEM is connected, no "
                   + "alerts arrive for this client.";
  installed.append(none);
}
for (const row of live) {
  const line = document.createElement("div");
  line.className = "tool-row";
  line.textContent = `${row.name} — ${row.health}`;
  if (row.last_error) line.textContent += `  ${row.last_error}`;
  installed.append(line);
}

// Pending is not connected. Saying so here was the difference between
// "this client is onboarded" and "this client cannot receive an alert".
if (waiting.length) {
  const note = document.createElement("div");
  note.className = "hint";
  note.textContent = `Still waiting on credentials for: ${
    waiting.map((t) => t.name).join(", ")}. Enter them under Integrations.`;
  installed.append(note);
}

// Alerts can only arrive from something that is connected.
const source = byName("intakeSource");
source.replaceChildren();
for (const row of tools.installed || []) {
  const option = document.createElement("option");
  option.value = row.connector_id;
  option.textContent = row.name;
  source.append(option);
}

return client;
})();

const { request, setText } = globalThis.SOAR;

return (async () => {
const credentials = {};
for (const role of tool.credential_roles || []) {
  const value = window.prompt(`${tool.name}\n\n${role}:`);
  if (!value) return null;
  credentials[role] = value;
}

if ((tool.min_vendor_permissions || []).length) {
  const ok = window.confirm(
    `${tool.name} needs these permissions on the vendor side:\n\n`
    + tool.min_vendor_permissions.join("\n")
    + "\n\nContinue?");
  if (!ok) return null;
}

try {
  const done = await request(
    "POST", `/api/clients/${encodeURIComponent(clientId)}/tools`,
    { connector_id: tool.id, credentials, config: {} });
  setText("statusMessage",
          `${done.connector} connected, ${done.commands} commands published`);
  await loadClient();
  return done;
} catch (error) {
  setText("statusMessage", `could not connect ${tool.name}: ${error.message}`);
  return null;
}
})();

const { byName, request, setText } = globalThis.SOAR;

return (async () => {
const id = new URLSearchParams(location.search).get("id");
try {
  await request("PATCH", `/api/clients/${encodeURIComponent(id)}`, {
    name: byName("clientNameInput").value,
    reference: byName("clientRefInput").value,
    contact_email: byName("clientContactInput").value,
    tier: byName("clientTierInput").value,
    timezone: byName("clientTzInput").value,
  });
  setText("statusMessage", "account saved");
  await loadClient();
} catch (error) {
  setText("statusMessage", `save failed: ${error.message}`);
}
return null;
})();

const { request, setText } = globalThis.SOAR;

const OURS = [
  ["vendor_alert_id", ""],
  ["title", ""],
  ["description", ""],
  ["raw_severity", ""],
  ["observed_at", ""],
  ["category", ""],
  ["technique_ids", ""],
];

const card = document.createElement("div");
card.className = "src";

const head = document.createElement("div");
head.className = "src-head";
const nm = document.createElement("span");
nm.className = "src-name";
nm.textContent = source.name;
const state = document.createElement("span");
state.className = "chip";
state.textContent = source.configured ? "configured" : "not configured";
head.append(nm, state);
card.append(head);

const body = document.createElement("div");
body.className = "src-body";
head.addEventListener("click", () => body.classList.toggle("is-open"));
if (!source.configured) body.classList.add("is-open");

// --- 1. how the JSON arrives ---------------------------------------
const transportBlock = document.createElement("div");
transportBlock.className = "sub";
const tTitle = document.createElement("div");
tTitle.className = "sub-title";
tTitle.textContent = "1 · API";
transportBlock.append(tTitle);

const transport = document.createElement("select");
for (const [value, text] of [
  ["webhook", "webhook - they POST each alert to us"],
  ["poll", "polling - we query their API on an interval"],
  ["none", "nothing arrives from this tool"],
]) {
  const option = document.createElement("option");
  option.value = value;
  option.textContent = text;
  transport.append(option);
}
transport.value = source.transport;
transportBlock.append(fieldRow("transport", transport));

const hook = document.createElement("input");
hook.type = "text";
hook.value = source.webhook_path || "";
const hookRow = fieldRow("webhook path", hook);
transportBlock.append(hookRow);

const every = document.createElement("input");
every.type = "number";
every.min = "30";
every.value = source.poll_interval_s || 300;
const everyRow = fieldRow("query every (seconds)", every);
transportBlock.append(everyRow);

const query = document.createElement("input");
query.type = "text";
query.placeholder = "vendor filter, e.g. status:new";
query.value = source.poll_query || "";
const queryRow = fieldRow("only fetch alerts matching", query);
transportBlock.append(queryRow);

const showTransport = () => {
  hookRow.hidden = transport.value !== "webhook";
  everyRow.hidden = transport.value !== "poll";
  queryRow.hidden = transport.value !== "poll";
};
transport.addEventListener("change", showTransport);
showTransport();
body.append(transportBlock);

// --- 2. what the fields mean ---------------------------------------
const mapBlock = document.createElement("div");
mapBlock.className = "sub";
const mTitle = document.createElement("div");
mTitle.className = "sub-title";
mTitle.textContent = "2 · INGESTION";
mapBlock.append(mTitle);


const mapInputs = {};
const knownFields = new Set(OURS.map(([field]) => field));

// The Common Security Event Model: the seven every screen and every
// playbook reads. Their names are fixed, so only the path is editable.
for (const [field, meaning] of OURS) {
  const row = document.createElement("div");
  row.className = "map-row";
  const ours = document.createElement("span");
  ours.className = "ours";
  ours.textContent = field;
  const input = document.createElement("input");
  input.type = "text";
  input.placeholder = meaning;
  const existing = source.field_map ? source.field_map[field] : "";
  input.value = typeof existing === "string" ? existing : "";
  mapInputs[field] = input;
  row.append(ours, input);
  mapBlock.append(row);
}

// --- anything else this vendor sends ---------------------------------
const extraHost = document.createElement("div");
mapBlock.append(extraHost);
const extras = [];

const addExtra = (name, path) => {
  const row = document.createElement("div");
  row.className = "map-row";
  const key = document.createElement("input");
  key.type = "text";
  key.className = "ours-input";
  key.placeholder = "";
  key.value = name || "";
  const value = document.createElement("input");
  value.type = "text";
  value.placeholder = "";
  value.value = path || "";
  const drop = document.createElement("button");
  drop.type = "button";
  drop.className = "ghost";
  drop.textContent = "−";
  const entry = { key, value, row };
  drop.addEventListener("click", () => {
    row.remove();
    const at = extras.indexOf(entry);
    if (at >= 0) extras.splice(at, 1);
  });
  extras.push(entry);
  row.append(key, value, drop);
  extraHost.append(row);
};

// Whatever was mapped last time under a name of the SOC's own.
for (const [field, path] of Object.entries(source.field_map || {})) {
  if (!knownFields.has(field) && typeof path === "string") {
    addExtra(field, path);
  }
}

const addMore = document.createElement("button");
addMore.type = "button";
addMore.className = "ghost";
addMore.textContent = "+ Add a field";
addMore.addEventListener("click", () => addExtra("", ""));
mapBlock.append(addMore);


const sample = document.createElement("textarea");
sample.className = "sample";
sample.placeholder = "A real alert from this tool, as JSON";
if (source.sample_payload) {
  sample.value = JSON.stringify(source.sample_payload, null, 2);
}
mapBlock.append(sample);

const tryIt = document.createElement("button");
tryIt.type = "button";
tryIt.className = "ghost";
tryIt.textContent = "Try the mapping on this alert";
const preview = document.createElement("div");
preview.className = "preview";
preview.hidden = true;

tryIt.addEventListener("click", async () => {
  let payload;
  try {
    payload = JSON.parse(sample.value);
  } catch (bad) {
    preview.hidden = false;
    preview.textContent = `That is not valid JSON: ${bad.message}`;
    return;
  }
  const field_map = {};
  for (const [field, input] of Object.entries(mapInputs)) {
    if (input.value.trim()) field_map[field] = input.value.trim();
  }
  for (const extra of extras) {
    const name = extra.key.value.trim();
    const path = extra.value.value.trim();
    if (name && path) field_map[name] = path;
  }
  try {
    const result = await request(
      "POST", `/api/clients/${encodeURIComponent(clientId)}/intake/preview`,
      { source: source.source, payload, field_map });
    preview.hidden = false;
    let text = JSON.stringify(result.alert, null, 2);
    if (result.unresolved.length) {
      text = `These paths matched nothing: ${result.unresolved.join(", ")}\n\n`
           + text;
    }
    if (result.problems.length) {
      text = `Would be rejected: ${result.problems.join("; ")}\n\n` + text;
    }
    preview.textContent = text;
  } catch (failure) {
    preview.hidden = false;
    preview.textContent = failure.message;
  }
});
mapBlock.append(tryIt, preview);
body.append(mapBlock);

// --- 3. and what happens to them is not decided here ---------------
const policyBlock = document.createElement("div");
policyBlock.className = "sub";
const pTitle = document.createElement("div");
pTitle.className = "sub-title";
pTitle.textContent = "3 · CONFIGURE PLAYBOOK";
policyBlock.append(pTitle);

// Severity, auto-close, enrichment and response used to be four inputs
// on this form that were saved and never read. They are playbook steps
// now: they run, they are versioned, an analyst can see which rule fired
// and why, and this client can differ from the next one without a column
// being added for it.
const note = document.createElement("div");
note.className = "conn-perms";
