const view = page.replace(/.html$/, "") || "index";
// The rail is rendered hidden and revealed from the permissions this
// session actually holds, so an analyst is not shown fifteen screens of
// which they can open four.
try {
  const me = await request("GET", "/api/me");
  // A tab that never saw the sign-in has no CSRF token, and every write
  // it attempts answers 403 while the session itself stays perfectly
  // valid. Recover it here, so a new tab is a working tab.
  try {
    if (me.csrf && !sessionStorage.getItem("soar.csrf")) {
      sessionStorage.setItem("soar.csrf", me.csrf);
    }
  } catch (ignored) { /* private mode: the meta tag stays the fallback */ }
  const held = me.permissions || [];
  for (const item of document.querySelectorAll("[data-permission]")) {
    if (held.includes(item.getAttribute("data-permission"))) {
      item.hidden = false;
    }
  }
  if (me.client_name) setText("activeClient", me.client_name);
} catch (error) {
