const pick = (name, label, options, selected) => {
  const select = document.createElement("select");
  const blank = document.createElement("option");
  blank.value = "";
  blank.textContent = label;
  select.append(blank);
  for (const option of options) {
    const item = document.createElement("option");
    item.value = option.value;
    item.textContent = option.label;
    if (option.value === selected) item.selected = true;
    select.append(item);
  }
  select.addEventListener("change", () => {
    const next = new URLSearchParams(location.search);
    if (select.value) next.set(name, select.value); else next.delete(name);
    window.location.search = next.toString();
  });
  filters.append(select);
  return select;
};

pick("client", "every client",
     (clients.items || []).map((c) => ({ value: c.id, label: c.name })),
