const copy = (source, target) => {
  for (const node of source.childNodes) {
    if (node.nodeType === Node.TEXT_NODE) {
      target.append(document.createTextNode(node.nodeValue));
      continue;
    }
    if (node.nodeType !== Node.ELEMENT_NODE) continue;
    if (!ALLOWED.has(node.tagName)) {
      // Not dropped silently: the text inside a disallowed tag is still
      // content somebody meant to show.
      copy(node, target);
      continue;
    }
    const made = document.createElement(node.tagName.toLowerCase());
    if (node.tagName === "A") {
      const href = node.getAttribute("href") || "";
      made.href = /^https?:\/\//i.test(href) ? href : "#";
      made.target = "_blank";
      made.rel = "noopener noreferrer";
    }
    copy(node, made);
    target.append(made);
  }
};
copy(parsed.body, host);
return host;

