const properties = {};
const required = [];
for (const entry of form.inputRows) {
  const fieldName = entry.fieldName.value.trim();
  if (!fieldName) continue;
  properties[fieldName] = { type: entry.type.value };
  if (entry.required.value === "yes") required.push(fieldName);
}
const outputs = {};
for (const entry of form.outputRows) {
  const fieldName = entry.fieldName.value.trim();
  if (!fieldName) continue;
  outputs[fieldName] = { type: entry.type.value };
}

const mutating = form.effect.value === "mutating";
const definition = {
  key: form.key.value.trim(),
  name: form.name.value.trim(),
  category: form.category.value.trim() || "custom",
  kind: form.mode.value === "python" ? "python" : "http",
  input_schema: { type: "object", required, properties,
                  additionalProperties: false },
  output_schema: { type: "object", properties: outputs },
  required_permissions: ["commands.execute"],
  // Set by the server from the trust level, not asked for here.
  timeout_ms: 30000,
  risk_level: form.risk.value,
  effect: form.effect.value,
  // A mutating command without one cannot be dry run honestly, and the
  // validator refuses it - so the form always sends one.
  dry_run_example: mutating
    ? { dry_run: true, would_run: form.key.value.trim() } : undefined,
  doc: "Written in the console.",
  clients: form.scope.value === "shared"
    ? form.boxes.filter((b) => b.checked).map((b) => b.value) : [],
};

if (form.mode.value === "python") {
  definition.implementation = { source: form.python.value };
} else {
  const extract = {};
  for (const pair of form.extract.value.split(",")) {
    const [outName, path] = pair.split("=").map((p) => p.trim());
    if (outName && path) extract[outName] = path;
  }
  let parsedBody = null;
  if (form.bodyTemplate.value.trim()) {
    try {
      parsedBody = JSON.parse(form.bodyTemplate.value);
    } catch (notJson) {
      setText("statusMessage", "the body is not valid JSON");
      return;
    }
  }
  definition.implementation = {
    method: form.method.value, url: form.url.value.trim(),
    headers: {}, body: parsedBody, extract,
    success_codes: [200, 201, 202, 204],
  };
}

