document.addEventListener("keydown", (event) => {
  const target = event.target;
  const typing = target instanceof HTMLElement &&
    (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable);

  if (event.key === "Escape" && typing) { target.blur(); return; }
  if (typing) return;

  if (pendingG && GO[event.key]) { pendingG = false; window.location.href = GO[event.key]; return; }
  pendingG = event.key === "g";
  if (pendingG) return;

  if (event.key === "/") { event.preventDefault(); document.querySelector(".omnibox")?.focus(); }
  if (event.key === "t") applyTheme(document.documentElement.getAttribute("data-theme") === "dark" ? "light" : "dark");
  if (event.key === "j") moveSelection(1);
  if (event.key === "k") moveSelection(-1);
});

