const { formatDuration, request, setText } = globalThis.SOAR;

return (async () => {
const id = new URLSearchParams(location.search).get("id");
if (!id) return;

const execution = await request("GET", `/api/executions/${encodeURIComponent(id)}`);
setText("execLabel", execution.label);
setText("execPlaybook", execution.playbook_name);
setText("execIncident", execution.incident_id || "—");
setText("execStarted", execution.started_at);
setText("execDuration", formatDuration((execution.duration_ms || 0) / 1000));
setText("execStatus", execution.status);
setText("execTrigger", `${execution.trigger_kind} ${execution.trigger_id || ""}`);
setText("execMode", execution.mode);

await refreshSteps(id);

const stream = new EventSource(`/api/executions/${encodeURIComponent(id)}/stream`);
stream.onmessage = () => refreshSteps(id);
stream.onerror = () => {
  // Fall back to polling rather than going quiet. A console that silently
  // stops updating during a containment run is worse than a slow one.
  stream.close();
  setInterval(() => refreshSteps(id), 4000);
};
})();

const { request } = globalThis.SOAR;

return (async () => {
const steps = await request("GET", `/api/executions/${encodeURIComponent(execution_id)}/steps`);
const list = document.querySelector('[data-name="stepList"], #steps');
if (!list) return;
list.replaceChildren();

for (const step of steps.items || []) {
  const item = document.createElement("li");
  item.dataset.status = step.status;
  item.tabIndex = 0;

  const dot = document.createElement("span");
  dot.className = "dot";
  dot.textContent = { succeeded: "\u2713", failed: "\u00d7", running: "\u25cf",
                      waiting_approval: "\u25c6", pending: "\u25cb",
                      skipped: "\u2013" }[step.status] || "\u25cb";

  const name = document.createElement("span");
  name.textContent = `${step.sequence}. ${step.node_id}` +
    (step.attempt > 1 ? `  (attempt ${step.attempt})` : "");

  const status = document.createElement("span");
  status.textContent = step.status;

  const duration = document.createElement("span");
  duration.textContent = step.duration_ms ? `${step.duration_ms}ms` : "";

  item.append(dot, name, status, duration);
  item.addEventListener("click", () => showStep(step));
  list.append(item);
}
})();

const { request, setText } = globalThis.SOAR;

return (async () => {
try {
  const health = await request("GET", "/readyz");
  const workers = await request("GET", "/api/admin/workers");
  const approvals = await request("GET", "/api/approvals?status=pending");
  setText("queueDepth", `queue ${health.queue_depth ?? 0}`);
  setText("workerState", `workers ${workers.up}/${workers.total}`);
  setText("pendingApprovals", `approvals ${approvals.total}`);
} catch (error) {
  setText("statusMessage", `status unavailable: ${error.message}`);
}
})();

const target = event?.currentTarget || event?.target;
const view = target?.dataset?.view;
if (!view) return;
event.preventDefault();
window.location.href = view === "dashboard" ? "/index.html" : `/${view}.html`;

const rows = [...document.querySelectorAll("tbody tr, .steps li")];
if (!rows.length) return;
const index = rows.findIndex((row) => row.classList.contains("is-selected"));
const next = Math.min(rows.length - 1, Math.max(0, (index < 0 ? 0 : index) + delta));
rows.forEach((row) => row.classList.remove("is-selected"));
rows[next].classList.add("is-selected");
rows[next].scrollIntoView({ block: "nearest" });

