const { request, setText } = globalThis.SOAR;

return (async () => {
const params = new URLSearchParams(location.search);
const id = params.get("id");
const version = params.get("version");

const ENDPOINTS = {
  load_incident:            ["GET",  () => `/api/incidents/${id}`],
  load_playbook:            ["GET",  () => `/api/playbooks/${id}/versions`],
  run_playbook_for_incident:["POST", () => `/api/playbooks/${prompt_playbook()}/run`],
  add_indicator:            ["POST", () => `/api/incidents/${id}/indicators`],
  accept_ai_analysis:       ["POST", () => `/api/ai/analyses/${analysis_id()}/accept`],
  validate_playbook_draft:  ["POST", () => `/api/playbooks/versions/${version}/validate`],
  start_dry_run:            ["POST", () => `/api/playbooks/${id}/dry-run`],
  start_simulation:         ["POST", () => `/api/playbooks/versions/${version}/simulate`],
  show_version_diff:        ["GET",  () => `/api/playbooks/${id}/diff`],
  publish_playbook:         ["POST", () => `/api/playbooks/versions/${version}/publish`],
  cancel_execution:         ["POST", () => `/api/executions/${id}/cancel`],
  resume_execution:         ["POST", () => `/api/executions/${id}/resume`],
};

if (action === "handle_omnibox_key") {
  if (event?.key !== "Enter") return;
  const query = event.currentTarget.value.trim();
  if (query) window.location.href = `/search.html?q=${encodeURIComponent(query)}`;
  return;
}

const route = ENDPOINTS[action];
if (!route) throw new Error(`no endpoint is registered for ${action}`);
const [method, path] = [route[0], route[1]()];
const result = await request(method, path, collect_form_body(action));
setText("statusMessage", `${action.replace(/_/g, " ")} ok`);
return result;
})();
